import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"鼎","description":"周易集解 - 鼎","frontmatter":{"title":"鼎","description":"周易集解 - 鼎"},"headers":[],"relativePath":"zh/classics/jijie/050.md","filePath":"zh/classics/jijie/050.md"}'),l={name:"zh/classics/jijie/050.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="鼎" tabindex="-1">鼎 <a class="header-anchor" href="#鼎" aria-label="Permalink to “鼎”">​</a></h1><h2 id="鼎-1" tabindex="-1">鼎 <a class="header-anchor" href="#鼎-1" aria-label="Permalink to “鼎”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>鼎，元吉，亨。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：革物者莫若鼎，故受之以鼎。</p><p>韓康伯曰：革去故，鼎取新以去故，則宜制器立法以治新也。鼎所和齊，生物成新之器也。故取象焉。</p><p>鄭玄曰：鼎，象也。卦有木火之用。互體乾兌。乾為金，兌為澤，澤鍾金而含水，爨以木火，鼎亨孰物之象。鼎亨孰以養人，猶聖君興仁義之道以教天下也，故謂之鼎矣。</p><p>虞翻曰：大壯上之初，與屯旁通。天地交，柔進上行，得中應乾五剛，故元吉亨也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：鼎，象也。以木巽火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。巽而耳目聰明，柔進而上行，得中而應乎剛，是以元亨。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>荀爽曰：震入離下，中有乾象。木火在外，金在其內，鼎鑊烹飪之象也。</p><p>虞翻曰：六十四卦，皆觀象繫辭，而獨於鼎言象，何也？象事知器，故獨言象也。</p><p>《九家易》曰：鼎言象者，卦也，木火互有乾兌。乾金兌澤。澤者，水也。爨以木火，是鼎鑊烹飪之象。亦明三公之位，上則調和陰陽，下而撫毓百姓，鼎能熟物養人，故雲象也。牛鼎受一斛，天子飾以黃金，諸侯白金。三足，以象三台，足上皆作鼻目為飾也。羊鼎五鬥，天子飾以黃金，諸侯白金，大夫以銅。豕鼎三鬥，天子飾以黃金，諸侯白金，大夫銅，士鐵。三鼎形同，亨飪煮肉，上離陰爻為肉也。</p><p>虞翻曰：聖人謂乾。初四易位，體大畜。震為帝，在乾天上，故曰上帝。體頤象，三動噬嗑食，故以享上帝也。大享謂天地養萬物，聖人養賢以及萬民。賢之能者，稱聖人矣。</p><p>虞翻曰：謂三也。三在巽上，動成坎離，有兩坎兩離象，乃稱聰明。日月相推而明生焉，故巽而耳目聰明。眇能視，不足以有明。聞言不信，聰不明。皆有一離一坎，象故也。</p><p>虞翻曰：柔謂五得上中，應乾五剛。巽為進。震為行。非謂應二剛，與睽五同義也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：木上有火，鼎。君子以正位凝命。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：木火相因，金在其間。調和五味，所以養人。鼎之象也。</p><p>虞翻曰：君子謂三也。鼎五爻失正，獨三得位，故以正位凝成也。體姤，謂陰始凝，初巽為命，故君子以正位凝命也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，鼎顛趾，利出否。得妾以其子，無咎。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：趾，足也。應在四。大壯震為足，折入大過。大過，顛也。故鼎顛趾也。</p><p>虞翻曰：初陰在下，故否。利出之四，故曰利出。兌為妾，四變得正成震。震為長子，繼世守宗廟，而為祭主。故得妾以其子，無咎矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鼎顛趾，未悖也。利出否，以從貴也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：以陰承陽，故未悖也。</p><p>虞翻曰：出初之四，承乾五，故以從貴也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，鼎有實，我仇有疾，不我能即，吉。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>虞翻曰：二為實，故鼎有實也。坤為我，謂四也。二據四婦，故相與為仇。謂三變時四體坎，坎為疾，故我仇有疾。四之二歷險，二動得正，故不我能即，吉。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鼎有實，慎所之也。我仇有疾，終無尤也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：二變之正，艮為慎。</p><p>虞翻曰：不我能即吉，故終無尤也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，鼎耳革，其行塞，雉膏不食。方雨，虧悔，終吉。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：動成兩坎，坎為耳，而革在乾，故鼎耳革。初四變時，震為行。鼎以耳行，伏坎震，折而入乾，故其行塞。離為雉，坎為膏。初四已變，三動體頤。頤中無物，離象不見，故雉膏不食。</p><p>虞翻曰：謂四已變，三動成坤。坤為方，坎為雨，故曰方雨。三動虧乾而失位，悔也。終復之正，故「方雨，虧悔，終吉」也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鼎耳革，失其義也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：鼎以耳行。耳革行塞，故失其義也。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，鼎折足，覆公餗，其形渥，凶。</p><h2 id="九四注" tabindex="-1">九四注 <a class="header-anchor" href="#九四注" aria-label="Permalink to “九四注”">​</a></h2><p>虞翻曰：謂四變時震為足，足折入兌故鼎折足。兌為形。渥，大形也。鼎足折，則公餗覆，言不勝任。象入大過死，凶。故「鼎足折，覆公餗，其形渥，凶」。</p><p>《九家易》曰：鼎者，三足一體，猶三公承天子也。三公謂調陰陽，鼎謂調五味。足折餗覆，猶三公不勝其任，傾敗天子之美。故曰覆餗也。</p><p>案：餗者，雉膏之屬。公者，四為諸侯，上公之位，故曰公餗。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：覆公餗，信如何也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：渥者，厚大，言罪重也。既覆公餗，信有大罪。刑罰當加，無可如何也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，鼎黃耳，金鉉，利貞。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：離為黃，三變坎為耳，故鼎黃耳。鉉謂三，貫鼎兩耳。乾為金。故金鉉。動而得正，故利貞。</p><p>乾寶曰：凡舉鼎者，鉉也。尚三公者，王也。金喻可貴，中之美也，故曰金鉉。鉉鼎得其物，施令得其道，故曰利貞也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：鼎黃耳，中以為實也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>陸績曰：得中承陽，故曰中以為實。</p><p>宋衷曰：五當耳中，色黃，故曰鼎黃耳。兌為金，又正秋，故曰金鉉。公侯，謂五也，上尊故玉，下卑故金。金和良，可柔屈，喻諸侯順天子。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，鼎玉鉉，大吉，無不利。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：鉉謂三，乾為玉鉉。體大有上九「自天祐之」，位貴據五，三動承上，故大吉無不利。謂三虧悔，應上成未濟。雖不當位，六位相應，故剛柔節。《彖》曰：「巽，耳目聰明」，為此九三發也。</p><p>乾寶曰：玉又貴於金者。凡烹飪之事，自鑊升於鼎。載於俎，自俎入於口。馨香上達，動而彌貴，故鼎之義，上爻愈吉也。鼎主烹飪，不失其和。金玉鉉之，不失其所。公卿仁賢，天王聖明之象也。君臣相臨，剛柔得節。故曰吉無不利也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：玉鉉在上，剛柔節也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>宋衷曰：以金承玉，君臣之節。上體乾為玉，故曰玉鉉。雖非其位，陰陽相承，剛柔之節也。</p>',80)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
